) AS (
  VALUES 
    (396::BIGINT, 'Una excelente opción para llevar este curso. Brinda mucho apoyo al estudiante (consultas, material extra, etc.) y siempre busca ayudar al estudiante. El curso es pesado por si solo, al ser muy teórico, pero con el profe se pasa muy sencillo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, '463ae30dc493766677faaba3a922c73afea3c7093778102f924e7aec59eb54b4'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'De lo mejor que tiene la escuela de electro. Explica muy claro, se nota que genuinamente le apasiona la materia y lo transmite. Dejó dos tareas fáciles, pero muy útiles si uno las hace a consciencia. Califica normal, eso de que califica binario no es cierto, solo que ya no taaan suave como antes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '7d42254f7e40bf9a0bf391aa6ed5a4ca5090a91711fae326b1280fec176324ac'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Siendo honest@, no sé que fue lo que pasó este semestre pero si calificó bien rudo, las clases son pesadas porque habla demasiado, recomiendo mejor estudiar de resúmenes apenas empieza el semestre. Calificó binario, solo hizo 2 tareas y la asistente califica rudo. Curso de mucha teoría.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c98c47a806ebeb70fffb7fdbd8ba6b466b290db6906a39e67ff83dffb2601c0d'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'El mejor profesor que he tenido de la carrera, imposible no amarlo. Si pudiera llevar toda mi carrera con él, lo haría, es de esos poquitos que sí se preocupan por sus estudiantes y sobre todo que aprendamos. JJ es un grande'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ac472dc31c00191e9e16fa630287c47e3519b97ba394efb09ef11e276d4a6e40'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Lo mismo que los demás comentarios. Excelente como profesor y persona, El mae se domina la materia a nivel super profundo, se nota que le gusta, tareas fáciles, pero muy útiles, da muchas herramientas, el único examen difícil es el de transistores. 10/10. +Tiene videos en Youtube'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '439676b6d7610310024202fb5e4e8edf59ae8e800536ff4ae17cbd7f68d26a69'::TEXT, ARRAY[3051]::BIGINT[]),
    (396::BIGINT, 'En realidad me costó un toque entenderle en las clases, pero es bueno, tanto como profe como persona, no siento que califique rudo en los exámenes, lo recomendaría'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, '3d9940f5fecf77933fcc076c579d43afe37d073b998fa4ac0778947070bf0e48'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Super recomendado para activos, ayuda demasiado cuando usted no entiende algo, y es muy atento para atender dudas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'd0e64a7b6f0ab8b05056ec6f92f75a4fe99cf18851f6229ff270a98ac29d4073'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'El profe es una excelente persona y un buen profesor. De los mejores que tiene la escuela. Tiene videos en YT donde hace ejercicios. A veces se confunde un poco pero nada del otro mundo. Siempre está dispuesto a ayudarle a uno a entender los contenidos, muy amable en consulta. Lo recomiendo un 100%.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'fea989a779fdb9dd375bb6dfa5712aeab46d81f7d0e50d2c88c1d4cddad6211f'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'El profesor explica demasiado bien y deja todo grabado, lo que ayuda mucho para repasar. Además, es una excelente persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'fa9cdb62f40b83c432c2d812ff5f0f6e34374f1b2ed00b3c9ac8c95f927e3a32'::TEXT, ARRAY[3051]::BIGINT[]),
    (396::BIGINT, 'Excelente como persona y profesor. Es uno de los pocos que de verdad busca el bien de los estudiantes y trata de ayudar lo máximo posible. El curso tiene su dificultad, pero con bastante práctica se pasa y el profe explica bastante bien, nada más revisen las presentaciones de la catedra.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '960bf03b979fde37d1828668fa97250496d23d1cd0f87d5978fb5fc78330f949'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'juan josé MONTERO ????el profe es súper buena persona, la materia puede ser aburrida al inicio pero luego tiene sentido, explica de una manera clara y simple, no se complica mucho, califica bien y enserio es un súper profesor demasiado amable, le interesa que usted entienda y que todos pasen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-12-01T00:00:00+00:00'::TIMESTAMPTZ, '0bc43158a8e9289bb8fc1bc5eef01d7bce41125c68d926d65de0034cb5d60a5b'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Excelente profesor, en veces se confunde un poco y al inicio Activos puede ser un poco aburrido por la materia. Pero en general le interesa demasiado que el estudiante aprenda y es super buena persona.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '22fb510c91ec6c41a5902d1a400cd2d095e00d1c3c72523da71bbbf4f7380b71'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Es muy buen profe y ayuda demasiado a los estudiantes, pero sus clases son aburridas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, '8702c0862b5050ec7db86765c26127daa89996ca1994dfe31d22ebce7d733c0a'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Probablemente lo mejor que hay en la escuela de Electro, lo que más le importa a el es que el estudiante aprenda y conozca para lo que sirve realmente la materia, no da el curso buscando quedar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '88682edbefd0dc5944c510a43afdbb7450d41b4c1975ab031b6066c8945c68de'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'No es obligado ir, tiene las clases en YT, es un amor de persona, explica bien, los exámenes no son a matar y los viejos los da con soluciones, si ocupas ayuda él te explica. Por algo todo mundo lo quiere y lo respeta, es todo lo que a la escuela de electro le falta. Lo tqm'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fc240f8dd47f19328fea4fb19dcacb867a11812755460c1cf5b03aa0b39d7ed5'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Es un excelente profesor, explica muy bien y se preocupa por que sus estudiantes aprendan. Da buena retroalimentación y hace práctica antes del examen lo que ayuda mucho.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-01-22T00:00:00+00:00'::TIMESTAMPTZ, '26009ffe228ecd9888b10845287502a05a23ceed3195ced483f3436c0001e805'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'De los mejores profesores de Electro. Es muy buena gente y siempre está dispuesto a ayudarlo a uno. La mejor opción para llevar Discretos'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, '8b0ea544a182d228525a0feba8197d80f148448a674a54bb876dd84a3b9d353c'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Este profe es GOD simplemente, hasta el momento el mejor profesor de electrónica que me he topado y por mucho. Explica demasiado bien, resuelve todas las dudas y es muy atento en todo. Sabe demasiado sobre el curso que da y da ejemplos sobre ya proyectos reales. Sin duda meta con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f3561847a44845056a44afc404d65e8a3ba3e9411eeb6e4c335f10802605752c'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, '11/10 definitivamente matricule con él. Es super comprensivo, sabe demasiado explica todo clarísimo. El curso es muy pesado en materia pero el profe lo abarca todo bien. Para los exámenes es suficiente con la materia que da el profe y las tutorías. Siempre da ejemplos de aplicación de la materia.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'a503a50684e1f574b75c89615537478d2778917bde8f68992638d1613a531abe'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'El mejor profe que hay en la escuela de electronica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-03-30T00:00:00+00:00'::TIMESTAMPTZ, 'dc8ba757cca8682aac211e9aa9f0c09e7b2a1525b62e55362f6c0d076b8a511b'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'A veces habla de temas por fuera de la materia que ayudan para la vida laboral, buen profesor, explica claro y las veces que sea necesario. La mayoria de tiempo al inicio de cada clase hace un repaso de la materia vista antes y eso ayuda a el estudiante a sintetizar la informacion'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'c564486e07edd4c5d0c2be0dfdfda06dc9ee541b836a4bae82a605a1c933b22f'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Este profe es GOD, no hace falta que lea más, si puede meta con él de fijo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'bfea66c820dfac803c7ca139d4da912314b050a37d33237bae4324fc7c2f367c'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Es un excelente profesor, muy amable, explica todo muy claro, da mucha práctica en clase, y ayuda al estudiante en lo que necesita. La materia al principio parece complicada pero conforme se avanza se va simplificando, para sus examenes basta con ver las clases y seguir los ejercicios'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '3c9672846156bf6f4e5f3d4abab1f3103894f6ecabb319e6c2489f5c60ab9040'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'De los mejores profe que me he topado en el TEC, es sumamente amable y siempre está dispuesto a ayudar, explica excelente, no dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '1698b0ef5da2f43e5ab1af878336add3c36bc1c10445f96ca1162d4019b8121b'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Un amor de persona y profesor, con ver las clases queda claro todo, los examenes no son tan dificiles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '216ce1127657af9f60ba38a484d374ce4a25caf63d6b3370a440dec87beaf884'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'El profe es excelente, explica muy bien la teoría del curso, no hace mucha práctica en clase pero con lo que explica ya uno por cuenta propia resuelve los ejercicios bien, el profe ayuda bastante con lo que son tareas, los enunciados de los examenes son muy claros y en general, lo recomiendo!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '84aef21f95c4005a3a26dddd150b33d72999e444f5e3efead0579bd8339220e4'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'El profe es súper claro con las explicaciones y siempre señala el capítulo del libro donde se encuentra la materia de la clase para repasar y llevarle dudas. Los exámenes son justos y premia bastante que se vean las clases, de forma sincrónica o asincrónica, no se requiere tanta práctica.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '1ba25f91433562be854f545617e53487d53fa36207de67014c2a81380563eae6'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Me gusta la forma en la que da el curso, no le da tanta importancia a la parte matematica como otros profesores, califica suave y es super buena gente, aunque a veces se enreda cuando explica y brinca de un tema al otro'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2cdb6a464ebf157a93cdff24c209ada81b34dbca94237e6bca22273931ea8198'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'El profe trata de abarcar siempre toda la materia y se nota que sabe mucho, es un crack, pero las clases suelen ser un poco teóricas entonces lo mejor es también hacer ejercicios por aparte porque los examenes los hacen muuy duros.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '2e065e75536eb4bef624a5f74e19d3a877c59c7e8d86c1d24d74b45b8f1f9c83'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'No falla JJ, un crack. En modalidad virtual da 5 días para hacer los exámenes, entonces es muy fácil sacarse buenas notas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '6cafeb2e3b5d6ac63604542b6507e33d684a539bdbe770fc6f8f45c34b3d3df0'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'El profe es tuanis, de los mejores profes que he tenido. Explica super bien y la materia la deja clara, también califica tuanis. Este semestre la cátedra fue un desorden. El primer examen estuvo duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases largas']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '253fa9bb77666e3cd04a14e6c0081ce8b0195ffa744a394a245b3c9f797e059e'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Es un buen profe , trata de ayudar al estudiante , explica bien solo que aveces se enreda bastante . Ayuda mucho para tareas o dudas y califica justo , sin maltratar tanto al estudiante . Lo malo es que sus clases son por directos de Youtube y el unico medio para consultas correo (dura mucho)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '60f3aa1279ea592005e6d059395b25e97645308cc6c9c01496e6e370a59f5fda'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Es un amor de profe, a veces puede desordenarse un poco, pero en general explica muy bien y se nota que sabe mucho. Es bastante comprensivo y razonable y se nota que no busca quedar a la gente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, '09535edefeb5a5481a04e909e4afaa8dfc29bbf7bdac303dfaecf24285b600c9'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Explica muy bien la teoría y resuelve bastantes ejercicios que de son mucha utilidad. Califica justo. Lo único malo es que no atiende las dudas por correo rápido o a veces ni las atiende. (y es el único medio para consultarle). En general, lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, '3f3068e3644a2b5b01a53048d1f474a8505688da6f4a07439ef6f685fb86e14c'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Excelente excelente, el profe es un amor y explica súper bien, la materia queda súper clara'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '284a1c2991a15e9d02d156b4cff482e71bd9009d64dc6b53a5febf5e079c8d58'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Excelente profesor, sabe demasiado y es sumamente claro con todo. Califica bastante cómodo y es muy buena gente a la hora de contestar dudas, no duden en matricular con él'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-09-16T00:00:00+00:00'::TIMESTAMPTZ, 'd5be4fe5817c7ee2492895a695ac9acbf06ec638a947e4c7be1cc583570b8bd4'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Barbosa, Juan Carlos, Pablo y Montero son la cara de eléctrónica, los únicos que salvan una escuela tan desagradable. Montero es un solecito, lleven con él a como sea posible.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'b9ed9fbede7179eaf0b486e279da4c2d0600e4ed0ef2eccb63501b12b0270408'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Es uno de los mejores profes que uno podría toparse en electro. En modalidad virtual es considerado con los estudiantes y uno aprende bastante en el curso. :) No dude matricular con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '5b144ede37e3262c9e942423edb80461befe22e883c92d75cad543d9736242cd'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'JJ es un amor, a veces se enreda un toque, pero es que hay que ver mucha materia jaja. Explica muy bien y no califica duro los exámenes y tareas. Un crack ese muchacho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'cfac001072b24f825aa0012d159a40d43c47d731891f023e95f346516bc5916f'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'JJ es tremendo profesor, si pueden metan con él. Explica muy bien, si uno pregunta, con mucho cariño responde. De lo mejor que hay en electro, califica bien. Las clases sí son largas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases largas']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'df01b8f8d1b223a388a15291b7344fe97f253c653215118c67fc708599c67836'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Un genio. La única esperanza de la Escuela de Electrónica. Ayuda muchísimo, excelente persona. Es justo y comprensivo. Maneja muy bien la materia y siempre está dispuesto a colaborar. Definitivamente un profesor inspiracional. Es bastante adorable, especialmente cuando se pone boina. -J'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '159cc911e563772aeb5c35b198bdfa15bcfed6ed96a0e9d3b25d8623e358b3d6'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Este mae promete y medio. El curso no es tan duro, él explica bien y cada vez que da fórmulas o algo importante, dice exactamente para qué se usaría en examen. Es todo pura vida, recomendadísimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '71a6e174633e6c07171f14e418f4dc2a13365f970ace5432add27222eabb496a'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Tiene muy dominado el curso, por lo que cualquier pregunta seguramente sea aclarada. Al calificar exámenes no solo valora resultados sino también procedimiento.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '765b2e0bef296102cb50e8f8c0b2a9d35668ad5bc78b991f50277327aad82407'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'fada2b9108c179550df4c5e0d270bad168d612992edb93fb34e4de9e1dbd9ead'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Excelente profesor. Excelente persona. Maneja a profundidad el tema. Ayuda muchísimo en evaluaciones. 11/10. Se destaca entre un montón de energúmenos de la escuela y en la coordinación de este curso. -J'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e468fec36cd5871737e6821abb1211cc8512bec495de5c4d4d72294630f60ffa'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'El profe es demasiado bueno, muestra gran dominio de la materia y siempre busca ayudarlo a uno para que pase. Si puede meter el curso con él, hágalo sin pensarlo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'f3d84f711e06cead37c4819057e5113b71098c1bfa6d5e0b1aedc9a380365ea4'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'Es de os mejores profes que hay en Electro, sabe demasiado del tema, siempre da ejemplos y en los exámenes si usted estudia le va bien, haga el propósito de ir a las tutorías o al menos de resolver los ejercicios, el profe se pasa de buena nota y se preocupa por que el estudiante aprenda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '3a321380724c0ea8ae59347cd9116de06ee0a22b9f1f9cf25710bd3138150f8d'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Es un excelente profesor, las clases son muy buenas aunque a veces explica rápido, hay que poner mucha atención para no perderse. Da muchos ejemplos. Los exámenes no son difíciles, es lo que se vio en la clase. Las tareas son sencillas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '18fc7b07040f52a9062bc05eb8890c509594d15c9741e9e632a5040c76094401'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'El mejor profe de electro, vaya a todas las clases, tome buenos apuntes y de fijo pasa.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'ec511dccd0b9b5a6b35cfbd127313097bae81b295dbaeba5b2e0365d3e4c939a'::TEXT, ARRAY[1267]::BIGINT[]),
    (396::BIGINT, 'De los mejores profes de electro. Tqm Montero'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-08-29T00:00:00+00:00'::TIMESTAMPTZ, '7a65038098b0da9ebfe56abeef20ee47d639cd1023efdc7c525b3272e011e127'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-07-30T00:00:00+00:00'::TIMESTAMPTZ, '67e4fbc8a23d98d5e489f2ca5d52ebec1034826df5768af5860b49e840c1a28c'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Un curso que tiene fama de ser duro y que nadie lo enseña bien, llega este crack y logra que usted pase con buena nota entendiendo con gran claridad la materia y sin quitar mas tiempo del necesario y sumado a eso una excelente persona. No dude en llevar con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '53194bc95c9760cccce22d386305d8b7784f0339175d0a791212cb1ff8c56c97'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Es el mejor profesor para este curso, explica la materia súper claro y el dominio es perfecto, pero es un curso que se le debe dedicar mucho tiempo y estudio, porque a como bien explica bien exige mucho dominio de la materia, en resumen es excelente.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4194ab4ec61e589fb5dd528407225b700336e622c32698d5a59abc51cab04bcf'::TEXT, ARRAY[1276]::BIGINT[]),
    (396::BIGINT, 'Excelente profesor! Domina muy bien la materia y explica claro. La mejor opción para este curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'faf2433dc4aeb1f3b590e1c0bd0f0654020b9d86b75e4550feb52611c9c5ebfb'::TEXT, ARRAY[1276]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
